187→// getFileChanges returns the current file changes from git status.
188→// Returns (modifiedFiles, untrackedFiles, deletedFiles, stagedFiles, error)
189→func getFileChanges() ([]string, []string, []string, []string, error) {
190→	repo, err := openRepository()
191→	if err != nil {
192→		return nil, nil, nil, nil, err
193→	}
194→
195→	worktree, err := repo.Worktree()
196→	if err != nil {
197→		return nil, nil, nil, nil, fmt.Errorf("getting worktree: %w", err)
198→	}
199→
200→	status, err := worktree.Status()
201→	if err != nil {
202→		return nil, nil, nil, nil, fmt.Errorf("getting status: %w", err)
203→	}
204→
205→	var modifiedFiles, untrackedFiles, deletedFiles, stagedFiles []string
206→
207→	for file, st := range status {
208→		// Skip .entire directory
209→		if paths.IsInfrastructurePath(file) {
210→			continue
211→		}
212→
213→		// Check staging area first
214→		switch st.Staging {
215→		case git.Added, git.Modified:
216→			stagedFiles = append(stagedFiles, file)
217→			continue
218→		case git.Deleted:
219→			deletedFiles = append(deletedFiles, file)
220→			continue
221→		case git.Unmodified, git.Renamed, git.Copied, git.UpdatedButUnmerged, git.Untracked:
222→			// Fall through to check worktree status
223→		}
224→
225→		// Check worktree status
226→		switch st.Worktree {
227→		case git.Modified:
228→			modifiedFiles = append(modifiedFiles, file)
229→		case git.Untracked:
230→			untrackedFiles = append(untrackedFiles, file)
231→		case git.Deleted:
232→			deletedFiles = append(deletedFiles, file)
233→		case git.Unmodified, git.Added, git.Renamed, git.Copied, git.UpdatedButUnmerged:
234→			// No action needed
235→		}
236→	}
237→
238→	// Sort for consistent output
239→	sort.Strings(modifiedFiles)
240→	sort.Strings(untrackedFiles)
241→	sort.Strings(deletedFiles)
242→	sort.Strings(stagedFiles)
243→
244→	return modifiedFiles, untrackedFiles, deletedFiles, stagedFiles, nil
245→}
